"""SQLite storage. One database file per workspace.

* ``home``  -> data/home.db : rooms, devices and readings entered or imported
               by the user ("observations").
* ``demo``  -> data/demo.db : reproducible SYNTHETIC data generated by
               backend/demo.py. Kept in a separate file so synthetic and
               user data can never be mixed.

The data folder can be changed with the environment variable SHEM_DATA_DIR
(the tests use a temporary folder).
"""

import json
import os
import sqlite3
import threading
from pathlib import Path

from .config import DEFAULT_SETTINGS

WORKSPACES = ("home", "demo")
WRITE_LOCK = threading.RLock()

SCHEMA = """
CREATE TABLE IF NOT EXISTS settings (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS rooms (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    name       TEXT NOT NULL,
    archived   INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now', 'localtime'))
);
CREATE UNIQUE INDEX IF NOT EXISTS rooms_name ON rooms(name COLLATE NOCASE);
CREATE TABLE IF NOT EXISTS devices (
    id                     INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id                INTEGER NOT NULL REFERENCES rooms(id),
    name                   TEXT NOT NULL,
    type                   TEXT NOT NULL,
    power_w                REAL NOT NULL,
    comfort_value_per_hour REAL NOT NULL,
    startup_cost           REAL NOT NULL DEFAULT 0,
    schedule               TEXT NOT NULL,          -- JSON list of 24 x 0/1
    mode                   TEXT NOT NULL DEFAULT 'auto',   -- auto | manual
    manual_state           TEXT NOT NULL DEFAULT 'OFF',    -- ON | OFF
    archived               INTEGER NOT NULL DEFAULT 0,
    created_at             TEXT NOT NULL DEFAULT (datetime('now', 'localtime'))
);
CREATE TABLE IF NOT EXISTS imports (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    filename   TEXT NOT NULL,
    rows       INTEGER NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now', 'localtime'))
);
CREATE TABLE IF NOT EXISTS readings (
    id           INTEGER PRIMARY KEY AUTOINCREMENT,
    room_id      INTEGER NOT NULL REFERENCES rooms(id),
    ts           TEXT NOT NULL,          -- local time 'YYYY-MM-DDTHH:MM', interval start
    motion       INTEGER NOT NULL,       -- 0 / 1
    occupied     INTEGER,                -- optional occupancy label 0 / 1 / NULL
    source       TEXT NOT NULL,          -- manual | csv | demo
    import_id    INTEGER REFERENCES imports(id),
    prior        REAL,
    prior_source TEXT,                   -- filter | hourly | default
    posterior    REAL,
    predicted    REAL,                   -- P(occupied during the interval)
    created_at   TEXT NOT NULL DEFAULT (datetime('now', 'localtime')),
    UNIQUE(room_id, ts)
);
CREATE INDEX IF NOT EXISTS readings_ts ON readings(ts);
CREATE TABLE IF NOT EXISTS decisions (
    id                 INTEGER PRIMARY KEY AUTOINCREMENT,
    reading_id         INTEGER NOT NULL REFERENCES readings(id),
    device_id          INTEGER NOT NULL REFERENCES devices(id),
    room_id            INTEGER NOT NULL REFERENCES rooms(id),
    ts                 TEXT NOT NULL,
    interval_minutes   INTEGER NOT NULL,
    mode               TEXT NOT NULL,     -- auto | manual
    scheduled          INTEGER NOT NULL,
    motion             INTEGER NOT NULL,
    prior              REAL NOT NULL,
    posterior          REAL NOT NULL,
    predicted          REAL NOT NULL,
    previous_state     TEXT NOT NULL,     -- ON | OFF before this interval
    q_on               REAL,
    q_off              REAL,
    horizon            INTEGER,
    action             TEXT NOT NULL,     -- ON | OFF
    baseline_action    TEXT NOT NULL,     -- what the plain schedule would do
    energy_wh          REAL NOT NULL,     -- estimated: rated power x run time
    baseline_energy_wh REAL NOT NULL,
    starts             INTEGER NOT NULL DEFAULT 0,
    baseline_starts    INTEGER NOT NULL DEFAULT 0,
    explanation        TEXT NOT NULL,
    params             TEXT NOT NULL,     -- JSON snapshot of the model parameters
    created_at         TEXT NOT NULL DEFAULT (datetime('now', 'localtime')),
    UNIQUE(reading_id, device_id)
);
CREATE INDEX IF NOT EXISTS decisions_ts ON decisions(ts);
CREATE INDEX IF NOT EXISTS decisions_device ON decisions(device_id, ts);
CREATE TABLE IF NOT EXISTS control_log (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    device_id  INTEGER NOT NULL REFERENCES devices(id),
    action     TEXT NOT NULL,
    detail     TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT (datetime('now', 'localtime'))
);
CREATE TABLE IF NOT EXISTS optimizations (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    device_id  INTEGER NOT NULL REFERENCES devices(id),
    result     TEXT NOT NULL,
    applied    INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT (datetime('now', 'localtime'))
);
"""


def data_dir():
    folder = Path(os.environ.get("SHEM_DATA_DIR") or Path(__file__).resolve().parent.parent / "data")
    folder.mkdir(parents=True, exist_ok=True)
    return folder


def db_path(workspace):
    if workspace not in WORKSPACES:
        raise ValueError(f"Unknown workspace '{workspace}'")
    return data_dir() / f"{workspace}.db"


def connect(workspace="home"):
    """Open a connection and make sure the schema exists."""
    conn = sqlite3.connect(db_path(workspace), timeout=10)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA foreign_keys = ON")
    conn.executescript(SCHEMA)
    return conn


def get_settings(conn):
    settings = dict(DEFAULT_SETTINGS)
    for row in conn.execute("SELECT key, value FROM settings"):
        if row["key"] in settings:
            settings[row["key"]] = json.loads(row["value"])
    return settings


def save_settings(conn, values):
    for key, value in values.items():
        conn.execute("INSERT INTO settings(key, value) VALUES (?, ?) "
                     "ON CONFLICT(key) DO UPDATE SET value = excluded.value",
                     (key, json.dumps(value)))


def rows(cursor):
    return [dict(row) for row in cursor]


TABLES = ("decisions", "control_log", "optimizations", "readings", "imports", "devices", "rooms",
          "settings")


def reset_workspace(workspace):
    """Empty every table of a workspace (used to regenerate the demo).

    Rows are deleted instead of removing the file, because Windows does not
    allow deleting a file that another connection still has open.
    """
    conn = connect(workspace)
    try:
        with conn:
            for table in TABLES:
                conn.execute(f"DELETE FROM {table}")
            conn.execute("DELETE FROM sqlite_sequence")
    finally:
        conn.close()
